"""Öğrenci devamsızlık kontrolü.

Devamsızlık sınırı %30'dur. Devamsızlık oranı %30'u AŞARSA öğrenci
devamsızlıktan kalır; tam %30 sınır içinde sayılır.
"""

DEVAMSIZLIK_SINIRI = 0.30


def devamsizlik_kontrol(toplam_ders: int, devamsiz_ders: int,
                        sinir: float = DEVAMSIZLIK_SINIRI) -> dict:
    """Devamsızlık oranını hesaplar ve öğrencinin durumunu döndürür."""
    if isinstance(toplam_ders, bool) or not isinstance(toplam_ders, int):
        raise TypeError("Toplam ders sayısı tam sayı olmalıdır.")
    if isinstance(devamsiz_ders, bool) or not isinstance(devamsiz_ders, int):
        raise TypeError("Devamsız ders sayısı tam sayı olmalıdır.")
    if toplam_ders <= 0:
        raise ValueError("Toplam ders sayısı 0'dan büyük olmalıdır.")
    if devamsiz_ders < 0:
        raise ValueError("Devamsız ders sayısı negatif olamaz.")
    if devamsiz_ders > toplam_ders:
        raise ValueError("Devamsız ders sayısı toplam ders sayısını aşamaz.")

    oran = devamsiz_ders / toplam_ders
    # Kayan nokta hatasını önlemek için tam sayı karşılaştırması:
    # devamsiz / toplam > sinir  <=>  devamsiz * 100 > sinir*100 * toplam
    kaldi = devamsiz_ders * 100 > round(sinir * 100) * toplam_ders
    izin_verilen = (round(sinir * 100) * toplam_ders) // 100

    return {
        "oran": oran,
        "kaldi": kaldi,
        "durum": "KALDI (devamsızlık sınırı aşıldı)" if kaldi else "GEÇTİ (sınır içinde)",
        "izin_verilen_devamsizlik": izin_verilen,
        "kalan_hak": max(izin_verilen - devamsiz_ders, 0),
    }


def _tam_sayi_oku(mesaj: str) -> int:
    while True:
        try:
            return int(input(mesaj))
        except ValueError:
            print("Lütfen geçerli bir tam sayı girin.")


def main() -> None:
    print("=== Öğrenci Devamsızlık Kontrolü (sınır %30) ===")
    ad = input("Öğrenci adı: ").strip() or "Öğrenci"
    toplam = _tam_sayi_oku("Toplam ders saati: ")
    devamsiz = _tam_sayi_oku("Devamsız olunan ders saati: ")

    try:
        sonuc = devamsizlik_kontrol(toplam, devamsiz)
    except (ValueError, TypeError) as hata:
        print(f"Hata: {hata}")
        return

    print(f"\n{ad}")
    print(f"  Devamsızlık oranı : %{sonuc['oran'] * 100:.2f}")
    print(f"  İzin verilen      : {sonuc['izin_verilen_devamsizlik']} saat")
    print(f"  Kalan hak         : {sonuc['kalan_hak']} saat")
    print(f"  Durum             : {sonuc['durum']}")


if __name__ == "__main__":
    main()
